examples:
fabric.submit.op_restrict::fetching;

fabric.submit;

fabric.submit.commit_group;
fabric.wait.sync_restrict::read 0;

// Two fabric.try_put operations, reading from buf0 and buf1, are issued, each in its own
// fabric submit group.
fabric.try_put.async.shared::cta.mbarrier::complete_tx::16B.mbarrier::report::fabric.relaxed.sys.b128 [dstLeId, dstLeOffData0], [buf0], 0x100, [mbar];
fabric.submit.commit_group;
fabric.try_put.async.shared::cta.mbarrier::complete_tx::16B.mbarrier::report::fabric.relaxed.sys.b128 [dstLeId, dstLeOffData1], [buf1], 0x100, [mbar];
fabric.submit.commit_group;

// Wait until at most one (the most recent) fabric submit group is pending.
fabric.wait.sync_restrict::read 1;
// The first group has completed reading buf0, so buf0 can be overwritten while the second
// group may still be in flight.
st.shared.b32  [buf0], val;
fence.proxy.async.shared::cta;
fabric.try_put.async.shared::cta.mbarrier::complete_tx::16B.mbarrier::report::fabric.relaxed.sys.b128 [dstLeId, dstLeOffData0], [buf0], 0x100, [mbar];
fabric.submit.commit_group;

// Wait for all prior fabric submit groups before arriving at the mbarrier.
fabric.wait.sync_restrict::read 0;

